 if(k==='TICKET_CREATED')return `filed ${t}`;if(k==='TICKET_CLOSED')return `closed ${t}`;if(k==='TICKET_RETRACTED')return `retracted ${t}`;if(k==='TICKET_SELECTED')return `chose ${t} to work on by itself`;
